{
  "decision": "propose",
  "reason": "The requested numeric occurrence is the test accuracy in summary.json at runs → evaluation/test → accuracy.mean. The value is already a mean over the declared test runs and is stored as a fraction. The exact value is 0.841, which matches the mean of the three runs in metrics.csv. The source material from paper/main.tex states 'The test accuracy is 84.1\\% on Data-A.' This confirms the identity, units, and derivation of the requested occurrence.",
  "proposal_input": {
    "additions": {
      "metrics": {
        "accuracy.mean": {
          "source": "results/summary.json",
          "field": "accuracy.mean",
          "unit": "fraction",
          "reduce": "mean",
          "where": {
            "split": "test",
            "dataset": "Data-A"
          }
        }
      },
      "occurrences": {
        "test_accuracy": {
          "file": "paper/main.tex",
          "anchor": {
            "exact": "84.1"
          },
          "metric": "accuracy.mean"
        }
      }
    },
    "rationale": {
      "accuracy.mean": "The mean accuracy value of 0.841 is derived from the three test runs in metrics.csv, which are all on Data-A. The value matches the mean computed from these runs and is stored as a fraction in summary.json.",
      "test_accuracy": "The occurrence 'The test accuracy is 84.1\\% on Data-A.' directly provides the value for the requested metric. The exact text anchors the occurrence to the specific value."
    }
  }
}
